() => {
  // Find the exact element that contains only "Something went wrong"
  const els = document.querySelectorAll('*');
  const results = [];
  for (const el of els) {
    if (el.textContent.trim() === 'Something went wrong') {
      // Get context: siblings, parent structure
      const parent = el.parentElement;
      const grandparent = parent?.parentElement;

      // Get preceding siblings text
      let prevSiblingText = '';
      let prevEl = el.previousElementSibling;
      while (prevEl) {
        prevSiblingText = prevEl.textContent.substring(0, 100) + ' | ' + prevSiblingText;
        prevEl = prevEl.previousElementSibling;
      }

      // Get the parent card's full data attributes and classes
      let card = el.closest('[class*="card"], [class*="Card"], [class*="project"], [class*="Project"]');

      results.push({
        tag: el.tagName,
        className: el.className,
        innerHTML: el.innerHTML,
        parentTag: parent?.tagName,
        parentClass: parent?.className,
        parentId: parent?.id,
        parentInnerHTML: parent?.innerHTML?.substring(0, 500),
        grandparentTag: grandparent?.tagName,
        grandparentClass: grandparent?.className,
        prevSiblings: prevSiblingText,
        cardFound: !!card,
        cardClass: card?.className,
        cardText: card?.textContent?.substring(0, 300)
      });
    }
  }
  return results;
}
